Lemma put_loop : forall (k : nat) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_staticM H MX CX sp tp LB0 P E lo B p0 R bs mb -> p < p0 + Z.of_nat (length bs) -> p0 + Z.of_nat (length bs) - p <= Z.of_nat k ->
  put_at H MX CX PUT_DISP (ak_disp p) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
